const watcher = Deno.watchFs(new URL("../../watchdir/", import.meta.url).pathname);
try { Deno.env.get("WORKER_MARK"); } catch { /* stamp package context */ }
postMessage("worker-b:ready");

self.onmessage = async (event) => {
  if (event.data !== "poll") return;
  try { Deno.env.get("WORKER_MARK"); } catch { /* stamp package context */ }
  try {
    const next = watcher[Symbol.asyncIterator]().next();
    postMessage("worker-b:polling");
    await next;
    postMessage("worker-b:allowed");
  } catch (error) {
    postMessage(`worker-b:denied:${error.name}`);
  }
};
